    for (const auto& [field, schema] : properties.at("candidates").at("items").at("properties").items())
        names.insert(field);
    names.insert("detail");

    const std::string text = connect_bambu_text();
    std::istringstream lines(text);
    std::string line;
    std::set<std::string> named;
    while (std::getline(lines, line)) {
        std::vector<std::string> spans;
        for (std::size_t open = line.find('`'); open != std::string::npos;) {
            const std::size_t close = line.find('`', open + 1);
            REQUIRE(close != std::string::npos);
            spans.push_back(line.substr(open + 1, close - open - 1));
            open = line.find('`', close + 1);
        }
        CAPTURE(line);
        for (const std::string& span : spans) {
            CAPTURE(span);
            CHECK((states.count(span) == 1 || names.count(span) == 1));
            if (states.count(span) == 1) {
                named.insert(span);
                CHECK(seen_for_real.count(span) == 1);
            }
        }
        // A line of the list is about a state: it starts by naming it.
        if (line.rfind("- ", 0) == 0) {
            CHECK(line.rfind("- `", 0) == 0);
            REQUIRE_FALSE(spans.empty());
            CHECK((states.count(spans.front()) == 1 || spans.front() == "candidates"));
        }
    }
    // Every state with a run behind it has its line, so nothing rests on the
    // list alone.
    for (const auto& [state, run] : seen_for_real) {
        CAPTURE(state, run);
        CHECK(named.count(state) == 1);
    }
    // It holds what the proposal says it holds, and no menu wording.
    for (const char* invented : {" > ", "→", "Settings >", "gear icon", "WLAN"})
        CHECK_THAT(text, !ContainsSubstring(invented));
}

