/* The panel's own notices -- printer_add's receipt and the plug-in notice
   (Figma "Printer chat" coverage): one subtle card, a heading of glyph and
   words, then what follows it, 8 apart. */
.printer-added,
.printer-plugin {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 8px;
  padding: 12px;
  border-radius: var(--radius-medium);
  background: var(--surface-subtle);
  box-shadow: inset 0 0 0 1px var(--border-subtle);
  font: var(--font-body-small);
}

.printer-notice-heading {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  min-width: 0;
  color: var(--text-primary);
  font: var(--font-body-small-bold);
}
.printer-notice-heading .jp-icon { margin: 0; }

.printer-notice-body { color: var(--text-secondary); }

.printer-added .printer-notice-heading { color: var(--status-success); }

/* The nozzle on the left, Undo on the right. */
.printer-added-detail {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  min-height: var(--button-link-height);
}
.printer-added-detail > small { font: var(--font-label); color: var(--text-secondary); }

/* Wraps rather than clips: the name is the fact to check. */
.printer-added-caption { min-width: 0; }
.printer-added-name {
  overflow-wrap: anywhere;
  color: inherit;
}

.printer-added-undo {
  flex: none;
  margin-left: auto;
}

/* Undone: the receipt stays, no longer a success. */
.printer-added-removed .printer-notice-heading { color: var(--text-primary); }

.printer-plugin-install {
  align-self: flex-start;
  padding: var(--button-primary-padding);
  border: 0;
  font: var(--font-body-small-bold);
}

.printer-plugin-installed .printer-notice-heading { color: var(--status-success); }

