    // same for the prompt cache; what a call may do depends on the session.
    // Finding and adding a printer belongs to an Add session: a Change or
    // Connect session is about a printer the person already has, and an add
    // there would save another printer and move the session onto it.
    if (m_mode != ConversationMode::Add && (handler == ToolHandler::PrinterIdentify || handler == ToolHandler::PrinterAdd))
        return ToolError{"not_in_this_conversation",
                         "This conversation is about " + m_printer_name + ", which is already set up; printers are not "
                         "found or added here. Tell the person that another printer is added with + Add printer on Home."};
    // The settings tools reach the project too; here they reach this
    }
    return use;
}

std::optional<AgentSkillUse> AgentHost::session_skill() const
{
    const std::optional<std::string> trigger = m_session_skill ? m_session_skill() : std::nullopt;
    if (!trigger)
        return std::nullopt;
    const auto skill = std::find_if(m_skills.begin(), m_skills.end(),
                                    [&trigger](const AgentSkill& candidate) { return candidate.trigger == *trigger; });
    if (skill == m_skills.end())
        return std::nullopt;
    AgentSkillUse use{skill->name, skill->text, nullptr, *trigger, {}};
    use.stays = true;
    return use;
}

std::optional<AgentSkillUse> AgentHost::fire_on_new_slice_failure(const std::string& conversation_id,
                                                              const WorkspaceSnapshot& workspace) const
{
    std::vector<std::uint64_t> fresh;
    for (const Workspace::WorkspacePlate& plate : workspace.plates)
        if (plate.slice_failure && m_slice_failures_told.count(plate.slice_failure->sequence) == 0)
            fresh.push_back(plate.slice_failure->sequence);
    if (fresh.empty())
// where it was started from, for which filament and printer): fired on the
// turn that note starts, so the model has the calibration skill without
// choosing it.
inline constexpr const char* kCalibrationStarted = "calibration_started";
// The person tried to connect a Bambu Lab printer in the printer chat, by
// opening the chat to connect it, by a connection tool call, or by linking a
// printer found on the network in the printer form. There is one such trigger
// per connection type, chosen by the app from the printer, and the skill stays
// in that conversation from then on (PrinterConversation::connection_skill).
inline constexpr const char* kConnectBambu = "connect_bambu";
} // namespace SkillTrigger

} // namespace Protocol

